import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.ticker as ticker
import matplotlib
matplotlib.use('Agg')
import base64
from io import BytesIO

# --- 1. Load Data ---
df = pd.read_csv('/app/benchmark/data.csv')
df['order_date'] = pd.to_datetime(df['order_date'])
df['year_month'] = df['order_date'].dt.to_period('M').astype(str)
df['year_quarter'] = df['order_date'].dt.to_period('Q').astype(str)

# --- 2. Calculate KPIs ---
total_revenue = df['revenue'].sum()
total_profit = df['profit'].sum()
avg_profit_margin = (total_profit / total_revenue) * 100 if total_revenue else 0
avg_order_value = total_revenue / len(df)
discount_utilization = (df['discount'] > 0).mean() * 100

def to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=120)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

# Apply a professional style
plt.style.use('bmh')
colors = ['#3498db', '#e74c3c', '#2ecc71', '#9b59b6', '#34495e']

# --- 3. Generate Charts ---

# Chart 1: Sales Trends Over Time (Monthly Revenue & Profit)
monthly = df.groupby('year_month')[['revenue', 'profit']].sum().reset_index()
fig1, ax1 = plt.subplots(figsize=(10, 5))
ax1.plot(monthly['year_month'], monthly['revenue'], marker='o', color=colors[0], label='Revenue')
ax1.plot(monthly['year_month'], monthly['profit'], marker='o', color=colors[2], label='Profit')
ax1.set_title('Monthly Revenue and Profit (2023-2024)', fontsize=14)
ax1.set_ylabel('Amount ($)')
ax1.yaxis.set_major_formatter(ticker.FuncFormatter(lambda x, p: format(int(x), ',')))
plt.xticks(rotation=45, ha='right')
ax1.legend()
plt.tight_layout()
chart_sales_trend = to_base64(fig1)

# Chart 2: Quarterly Volume
quarterly = df.groupby('year_quarter')['quantity'].sum().reset_index()
fig2, ax2 = plt.subplots(figsize=(10, 5))
bars = ax2.bar(quarterly['year_quarter'], quarterly['quantity'], color=colors[0])
ax2.set_title('Quarterly Sales Volume (Units Sold)', fontsize=14)
ax2.set_ylabel('Units')
ax2.yaxis.set_major_formatter(ticker.FuncFormatter(lambda x, p: format(int(x), ',')))
plt.tight_layout()
chart_q_volume = to_base64(fig2)

# Chart 3: Top 10 Products by Revenue
top_products = df.groupby('product_id')['revenue'].sum().sort_values(ascending=False).head(10)
fig3, ax3 = plt.subplots(figsize=(8, 5))
top_products.sort_values().plot(kind='barh', color=colors[3], ax=ax3)
ax3.set_title('Top 10 Products by Revenue', fontsize=14)
ax3.set_xlabel('Revenue ($)')
ax3.set_ylabel('Product ID')
ax3.xaxis.set_major_formatter(ticker.FuncFormatter(lambda x, p: format(int(x), ',')))
plt.tight_layout()
chart_products = to_base64(fig3)

# Chart 4: Top 10 Stores by Revenue
top_stores = df.groupby('store_id')['revenue'].sum().sort_values(ascending=False).head(10)
fig4, ax4 = plt.subplots(figsize=(8, 5))
top_stores.sort_values().plot(kind='barh', color=colors[1], ax=ax4)
ax4.set_title('Top 10 Stores by Revenue', fontsize=14)
ax4.set_xlabel('Revenue ($)')
ax4.set_ylabel('Store ID')
ax4.xaxis.set_major_formatter(ticker.FuncFormatter(lambda x, p: format(int(x), ',')))
plt.tight_layout()
chart_stores = to_base64(fig4)

# Chart 5: Discount Impact (Average Profit Margin & Volume by Discount Level)
# Bin discounts to clean up
df['discount_level'] = (df['discount'] * 100).round(1).astype(str) + '%'
discount_stats = df.groupby('discount_level').agg(
    avg_margin=pd.NamedAgg(column='profit', aggfunc=lambda x: (x.sum() / df.loc[x.index, 'revenue'].sum()) * 100),
    avg_qty=pd.NamedAgg(column='quantity', aggfunc='mean')
).reset_index()
# Sort numerically by parsing the string back to float
discount_stats['sort_val'] = discount_stats['discount_level'].str.rstrip('%').astype(float)
discount_stats = discount_stats.sort_values('sort_val')

fig5, ax5 = plt.subplots(figsize=(10, 5))
ax5.bar(discount_stats['discount_level'], discount_stats['avg_margin'], color=colors[0], label='Avg Profit Margin (%)')
ax5_2 = ax5.twinx()
ax5_2.plot(discount_stats['discount_level'], discount_stats['avg_qty'], color=colors[1], marker='o', label='Avg Quantity per Order', linewidth=2)
ax5.set_title('Discount Impact: Profit Margin vs. Avg Quantity', fontsize=14)
ax5.set_xlabel('Discount Level')
ax5.set_ylabel('Profit Margin (%)', color=colors[0])
ax5_2.set_ylabel('Avg Quantity', color=colors[1])
# add legend handling for twinx
lines, labels = ax5.get_legend_handles_labels()
lines2, labels2 = ax5_2.get_legend_handles_labels()
ax5.legend(lines + lines2, labels + labels2, loc='upper right')
plt.tight_layout()
chart_discounts = to_base64(fig5)

